const THEMES_BY_PACK: Readonly<Record<string, readonly Theme[]>> = {
  'built-in-food-drink': FOOD_THEMES,
  'built-in-technology-inventions': TECHNOLOGY_THEMES,
  'built-in-politics-economics-society': SOCIETY_THEMES,
  'built-in-mythology-religion-philosophy': MYTHOLOGY_THEMES,
};

const assignedTargets = PLAYABLE_TARGETS.filter(({ batchId }) =>
  ASSIGNED_BATCH_IDS.has(batchId));

function sourceTitle(page: string): string {
  return decodeURIComponent(page.split('#', 1)[0]!.replaceAll('_', ' '));
}

function buildQuestion(
  target: PlayableTarget,
  theme: Theme,
  item: Item,
  tier: 1 | 2 | 3 | 4 | 5,
): PlayableQuestion {
  const [
    subjectKey,
    responseEn,
    responseEt,
    wikipediaPage,
    mediumPredicateEn,
    mediumPredicateEt,
    hardPredicateEn,
    hardPredicateEt,
    variantsEn = [],
    variantsEt = [],
  ] = item;
  const predicateEn = target.difficulty === 'medium' ? mediumPredicateEn : hardPredicateEn;
  const predicateEt = target.difficulty === 'medium' ? mediumPredicateEt : hardPredicateEt;
  return {
    key: `${target.categorySetId}:question:${tier}`,
    factKey: `${target.packId}:${theme.id}:${target.difficulty}:${subjectKey}`,
    tier,
    subjectKey,
    clue: {
      en: `${theme.prompt.en} ${predicateEn}?`,
      et: `${theme.prompt.et} ${predicateEt}?`,
    },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variantsEn, et: variantsEt },
    explanation: {
      en: `${responseEn} ${predicateEn}.`,
      et: `${responseEt} ${predicateEt}.`,
    },
    source: {
      sourceId: `wikipedia:${wikipediaPage.toLocaleLowerCase('en')}`,
      title: sourceTitle(wikipediaPage),
      url: `https://en.wikipedia.org/wiki/${wikipediaPage}`,
      license: 'CC-BY-SA-4.0',
      retrievedAt: '2026-08-28',
    },
  };
}

const targetCounters = new Map<string, number>();
const rawCategories: readonly PlayableCategory[] = assignedTargets.map((target) => {
  const themes = THEMES_BY_PACK[target.packId];
  if (themes === undefined) throw new Error(`Missing authored themes for ${target.packId}`);
  const eligibleThemes = target.difficulty === 'medium'
    ? themes.filter(({ mediumName }) => mediumName !== undefined)
    : themes;
  const counterKey = `${target.packId}:${target.difficulty}`;
  const themeIndex = targetCounters.get(counterKey) ?? 0;
  targetCounters.set(counterKey, themeIndex + 1);
  const theme = eligibleThemes[themeIndex];
  if (theme === undefined) throw new Error(`Missing theme ${themeIndex + 1} for ${counterKey}`);
  const name = target.difficulty === 'medium' ? theme.mediumName : theme.hardName;
  if (name === undefined) throw new Error(`Theme ${theme.id} has no medium title`);
  return {
    categorySetId: target.categorySetId,
    batchId: target.batchId,
    packId: target.packId,
    difficulty: target.difficulty,
    name,
    questions: theme.items.map((item, index) => buildQuestion(
      target,
      theme,
      item,
      (index + 1) as 1 | 2 | 3 | 4 | 5,
    )),
  };
});

export const PACKS_09_TO_12_CATEGORIES: readonly PlayableCategory[] = validatePlayableCorpus(
  rawCategories,
  assignedTargets,
);
